// Northpin service worker. GENERATED by scripts/build-sw.mjs after `next build` from scripts/sw.template.js:
// edit the template, not public/sw.js. Project data lives in IndexedDB on the device; this keeps the app itself
// (every page and every JS/CSS chunk of this build) available with no signal. See docs/offline.md.
const BUILD = __BUILD__;
const PRECACHE = __PRECACHE__;
const PREFIX = "pinplan-";
const CACHE = PREFIX + BUILD;
// Remembers which builds were activated, oldest first, so the previous build's cache can stay for one version:
// a tab still running the old build can keep lazy-loading its old chunks until it reloads.
const META = "pinplan-meta";
const KEEP_BUILDS = 2;
const OFFLINE = "/offline";
/** How long a page load waits for the network before using the saved copy (weak signal on site). */
const NAV_TIMEOUT_MS = 4000;

/** A same-origin, successful, non-redirected response is safe to keep (and to answer a navigation with). */
function cacheable(res) {
  return !!res && res.ok && res.type === "basic" && !res.redirected;
}

/** Fetch one URL fresh and store it. Never throws: one missing chunk must not stop the rest from being cached. */
async function precacheOne(cache, url) {
  const res = await fetch(new Request(url, { cache: "reload", credentials: "same-origin" }));
  if (!cacheable(res)) throw new Error(`${url}: ${res.status}`);
  await cache.put(url, res);
}

self.addEventListener("install", (event) => {
  // No skipWaiting here: the new version waits until the page asks for it (UpdatePrompt → "Reload"), so a deploy
  // never swaps chunks under an open tab.
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      Promise.allSettled(PRECACHE.map((url) => precacheOne(cache, url))).then((results) => {
        const failed = results.filter((r) => r.status === "rejected").length;
        if (failed) console.warn(`[sw] ${failed} of ${PRECACHE.length} files could not be cached for offline use`);
      }),
    ),
  );
});

/** Record this build as the newest and return the cache names to keep (this build and the one before it). */
async function rememberBuild() {
  const meta = await caches.open(META);
  let builds = [];
  try {
    const hit = await meta.match("/__builds");
    if (hit) builds = await hit.json();
  } catch {
    builds = [];
  }
  if (!Array.isArray(builds)) builds = [];
  builds = [...builds.filter((b) => b !== BUILD), BUILD].slice(-KEEP_BUILDS);
  await meta.put("/__builds", new Response(JSON.stringify(builds), { headers: { "content-type": "application/json" } }));
  return new Set(builds.map((b) => PREFIX + b));
}

self.addEventListener("activate", (event) => {
  event.waitUntil(
    rememberBuild()
      .then((keep) => caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== META && !keep.has(k)).map((k) => caches.delete(k)))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

/** Cached copy of a page, ignoring the query (/project?id=… is the same static page for every job). */
async function cachedPage(pathname) {
  const own = await caches.open(CACHE);
  return (await own.match(pathname)) || (await caches.match(pathname)) || (await own.match(OFFLINE)) || (await caches.match(OFFLINE));
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin || url.pathname.startsWith("/api/")) return;

  // Pages: network first so a deploy shows up right away; offline, the cached page, else the offline page. On a weak
  // signal (the network neither answers nor fails within NAV_TIMEOUT_MS) the saved copy of the page is used instead
  // of a blank screen; the network answer still refreshes the saved copy when it arrives.
  if (req.mode === "navigate") {
    const network = fetch(req).then((res) => {
      if (cacheable(res)) {
        const copy = res.clone();
        event.waitUntil(caches.open(CACHE).then((c) => c.put(url.pathname, copy)).catch(() => undefined));
      }
      return res;
    });
    const fallback = async () => (await cachedPage(url.pathname)) || Response.error();
    let timer;
    const slow = new Promise((resolve) => {
      timer = setTimeout(async () => {
        const own = await caches.open(CACHE);
        const hit = (await own.match(url.pathname)) || (await caches.match(url.pathname));
        if (hit) resolve(hit);
      }, NAV_TIMEOUT_MS);
    });
    const answered = network.catch(fallback);
    answered.finally(() => clearTimeout(timer)).catch(() => undefined);
    // Keep the worker alive until the network settles so the late answer can still refresh the saved page.
    event.waitUntil(network.then(() => undefined, () => undefined));
    event.respondWith(Promise.race([answered, slow]));
    return;
  }

  // React Server Component payloads for client-side navigation vary by router state: never cache them. Offline,
  // the router falls back to a full navigation, which the branch above answers from the cache.
  if (url.searchParams.has("_rsc") || req.headers.get("RSC") === "1") return;

  // Build files (/_next/static, content-hashed), the PDF.js worker and vendored libraries: cache first, they never
  // change at the same URL. Other files (icons, manifest): network first, cache as a fallback.
  const immutable = url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/vendor/") || /^\/pdf\.worker\.[\w.-]+\.mjs$/.test(url.pathname);
  const asset = immutable || /\.(js|mjs|css|svg|png|jpg|webp|ico|woff2?|webmanifest)$/.test(url.pathname);
  if (!asset) return;
  const save = (res) => {
    if (cacheable(res)) {
      const copy = res.clone();
      event.waitUntil(caches.open(CACHE).then((c) => c.put(req, copy)).catch(() => undefined));
    }
    return res;
  };
  // A worker takes its location from the response it is served; a cached response has lost the #params=… fragment
  // Turbopack passes its bootstrap config in, so hand workers a fresh copy that keeps the script's own URL.
  const worker = req.destination === "worker" || req.destination === "sharedworker";
  const fromCache = (hit) => (worker ? new Response(hit.body, { status: hit.status, statusText: hit.statusText, headers: hit.headers }) : hit);
  if (immutable) {
    event.respondWith(caches.match(req).then((hit) => (hit ? fromCache(hit) : fetch(req).then(save))));
  } else {
    event.respondWith(
      fetch(req)
        .then(save)
        .catch(async () => (await caches.match(req)) || Response.error()),
    );
  }
});
